<?php $showOwner=is_admin();$showAdminActions=$showOwner&&empty($compact);$cols=$showOwner?7:6;?>
<div class="table-scroll"><table class="ideas-table"><thead><tr><th>عنوان الفكرة</th><?php if($showOwner):?><th>مقدم الفكرة</th><?php endif?><th>الإدارة</th><th>الحالة</th><th>تاريخ الإرسال</th><th>التقييم من 5</th><th><?=$showAdminActions?'القرارات':'التفاصيل'?></th></tr></thead><tbody>
<?php if(!$tableIdeas):?><tr><td colspan="<?=$cols?>" class="empty-cell">لا توجد أفكار مطابقة.</td></tr><?php endif?>
<?php foreach($tableIdeas as $idea):$status=(string)($idea['status']??'');?><tr class="clickable-row" data-href="<?=url('details',['id'=>$idea['id']])?>"><td><strong><?=e($idea['title'])?></strong><?php if(empty($compact)):?><small><?=e($idea['number'])?></small><?php endif?></td><?php if($showOwner):?><td><strong class="employee-name"><?=e($idea['employee']??'غير محدد')?></strong></td><?php endif?><td><?=e($idea['department']?:'أخرى')?></td><td><span class="status status-<?=e($status)?>"><?=e(status_text($status))?></span></td><td><?=e(ar_date($idea['date']))?></td><td><?php if(is_numeric($idea['score']??null)):?><span class="table-score"><?=number_format((float)$idea['score'],1)?>/5 <?=icon('star',15)?></span><?php else:?>—<?php endif?></td><td><?php if($showAdminActions):?><form method="post" class="table-decision-actions"><input type="hidden" name="form_action" value="admin_idea_decision"><input type="hidden" name="idea_id" value="<?=e((string)$idea['id'])?>"><input type="hidden" name="return_to" value="ideas"><button class="icon-decision reject" name="decision" value="rejected" title="رفض الفكرة" aria-label="رفض الفكرة"><?=icon('close',17)?></button><?php if($status==='evaluated'):?><button class="icon-decision approve" name="decision" value="approved" title="ترشيح للتنفيذ" aria-label="ترشيح للتنفيذ"><?=icon('check',17)?></button><?php endif?></form><?php else:?><a class="row-menu" href="<?=url('details',['id'=>$idea['id']])?>" title="عرض التفاصيل"><?=icon('more',20)?></a><?php endif?></td></tr><?php endforeach?></tbody></table></div>
